			    vaCheckRows.forEach(function(idx){
			        var voRowData = app.lookup("grdList").getRow(idx).getRowData();
			        ds1.addRow().setValue("QUSTNB_TMPT_MNG_NO", voRowData["QUSTNB_TMPT_MNG_NO"]);
			    });
			    
